import{obterJSON,endereco,consultaLimpa,variantesBusca,pontuarCorrespondencia}from'./comum.js';
const fontes=[['pt','https://pt.wikisource.org'],['en','https://en.wikisource.org'],['es','https://es.wikisource.org'],['fr','https://fr.wikisource.org']];
async function consultar(base,idioma,termo,pagina,exato=false){const limite=50,offset=(pagina-1)*limite,u=new URL(base+'/w/api.php'),q=exato?`intitle:"${termo.replace(/"/g,' ')}"`:termo;Object.entries({action:'query',list:'search',srsearch:q,srnamespace:'0',srlimit:String(limite),sroffset:String(offset),srinfo:'totalhits',format:'json',origin:'*'}).forEach(([k,v])=>u.searchParams.set(k,v));const d=await obterJSON(u,14000,3);const itens=d.query?.search||[],total=Number(d.query?.searchinfo?.totalhits)||itens.length;return{livros:itens.map(p=>{const url=endereco(`${base}/wiki/${encodeURIComponent(String(p.title||'').replace(/ /g,'_'))}`);return url?{id:`wikisource:${idioma}:${p.pageid}`,fonte:'wikisource',provedor:`Wikisource ${idioma.toUpperCase()}`,titulo:p.title,autores:[],idiomas:[idioma],capa:null,acessoLivre:true,dominioPublico:false,tipoAcesso:'Leitura integral',licenca:'Texto disponibilizado pelo Wikisource. Consulte a página para autoria, integridade e licença da edição.',origem:url,ler:url,texto:null,formatos:[]}:null}).filter(Boolean),total,temMais:itens.length===limite&&offset+itens.length<total}}
function incorporar(mapa,respostas,termo){let total=0,temMais=false,sucessos=0;for(const r of respostas){if(r.status!=='fulfilled')continue;sucessos++;total+=r.value.total||0;temMais||=Boolean(r.value.temMais);for(const l of r.value.livros||[]){l.relevancia=pontuarCorrespondencia(termo,l.titulo,[]);if(!mapa.has(l.id))mapa.set(l.id,l)}}return{total,temMais,sucessos}}
export async function pesquisarWikisource(q,o={}){
 const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),vars=variantesBusca(termo),mapa=new Map();
 const gerais=await Promise.allSettled(fontes.map(([idioma,base])=>consultar(base,idioma,vars[0],pagina,false))),base=incorporar(mapa,gerais,termo);let total=base.total,temMais=base.temMais,sucessos=base.sucessos;
 if(pagina===1&&![...mapa.values()].some(l=>(l.relevancia||0)>=7000)){
  const exatas=await Promise.allSettled(fontes.map(([idioma,host])=>consultar(host,idioma,vars[0],1,true))),extra=incorporar(mapa,exatas,termo);sucessos+=extra.sucessos;
 }
 if(!sucessos)throw new Error('Wikisource indisponível');const livros=[...mapa.values()].sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));return{livros,total:total||livros.length,temMais};
}
